const item = $json;
const annee = new Date(item.date).getFullYear();
const queries = [
  `${item.theme_label} tendance ${annee} dropshipping avis prix`,
  `site:aliexpress.com ${item.theme_label}`,
  `site:cjdropshipping.com ${item.theme_label}`,
  `site:bigbuy.eu ${item.theme_label}`,
  `meilleur ${item.theme_label} ${annee} comparatif prix`
];
return [{ json: { ...item, searchBody: queries.map(q => ({ q, gl: 'fr', hl: 'fr', num: 5 })) } }];

const item = $('Construire requetes recherche').item.json;
const batchResults = $json; // reponse Serper.dev : tableau, un element par requete

let lines = [];
let seen = new Set();
for (const result of (Array.isArray(batchResults) ? batchResults : [batchResults])) {
  for (const o of (result.organic || [])) {
    if (!o.link || seen.has(o.link)) continue;
    seen.add(o.link);
    lines.push(`- [${o.title}](${o.link}) — ${o.snippet || ''}`);
  }
}
const resultatsRecherche = lines.length
  ? lines.join('\n')
  : "(aucun resultat exploitable trouve par la recherche n8n pour ces requetes — le dire honnetement dans le rapport plutot que d'inventer)";

const prompt = `Tu es l'agent RAYON specialise de la categorie "${item.categorie_label}" pour le site de dropshipping drop-shipper.fr, base en France.
Rapport du jour : ${item.date}, sous-theme "${item.theme_label}" (id: ${item.theme_id}).

Tu ne fais PAS de recherche web toi-meme : n8n a deja execute les requetes et te fournit ci-dessous les resultats REELS (titre, URL, extrait) obtenus sur le web.
REGLE ABSOLUE : n'utilise QUE les URLs presentes dans ces resultats pour les colonnes "URL fournisseur" et "URL plateforme conseillée". Si aucune URL exploitable n'apparait pour un produit que tu identifies comme pertinent, dis-le honnetement dans la colonne "Pourquoi" au lieu d'inventer une adresse.

A partir de ces resultats, identifie 20 produits gagnants dans ce sous-theme : forte marge, tendance actuelle, stock/livraison Europe si possible, prix bas a moyen, en croisant les fournisseurs (AliExpress, CJ Dropshipping, BigBuy, Temu, Wish, JoyBuy, Faire) quand ils apparaissent dans les resultats.

Respecte EXACTEMENT ce contrat de sortie (Markdown, rien avant ni apres) :

---
type: rayon
date: ${item.date}
categorie: ${item.categorie_id}
theme: ${item.theme_id}
titre: <titre court en francais>
agent: rayon-${item.categorie_id}
sources: <nombre de sources distinctes citees>
---

## Analyse
(marche, saisonnalite, gammes de prix, ce qui monte, ce qui sature, pieges, sources en liens, niveau directeur marketing)

## 20 produits proposés
Tableau Markdown avec EXACTEMENT ces colonnes dans cet ordre :
| # | Titre | Fournisseur | URL fournisseur | Prix achat € | Prix vente conseillé € | Marge % | Import | Pourquoi | URL plateforme conseillée |

Regles du tableau : Import vaut "api" (CJ Dropshipping/BigBuy/AliExpress relies par cle), "url" (fiche lisible par simple adresse) ou "extension" (Temu/AliExpress sans cle/Shein/SUPER DELIVERY, page JavaScript). Classe les produits "api"/"url" AVANT les produits "extension". Sois honnete sur le niveau de verification de chaque donnee. Reponds en francais.

Resultats de recherche web (fournis par n8n) :
${resultatsRecherche}`;

return [{ json: { ...item, rayonPrompt: prompt } }];

const response = $json;
const markdown = (response.response || '').trim();
const item = $('Agreger recherche + construire prompt').item.json;
const binary = await this.helpers.prepareBinaryData(Buffer.from(markdown, 'utf8'), `${item.theme_id}.rayon.md`, 'text/markdown');
return [{ json: { ...item, rayonMarkdown: markdown, rayonPath: `${item.basePath}/rapports/${item.date}/${item.categorie_id}/${item.theme_id}.rayon.md` }, binary: { data: binary } }];
